css:
.d-ts{box-sizing:border-box;width:236px;max-width:100%;height:150px;display:grid;place-items:center;perspective:700px;outline:none}
.d-ts-deck{--rx:0deg;--ry:0deg;position:relative;width:196px;height:92px;transform-style:preserve-3d;transform:rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));transition:transform 180ms cubic-bezier(.34,1.56,.64,1);will-change:transform}
.d-ts-card{position:absolute;inset:0;box-sizing:border-box;display:flex;flex-direction:column;justify-content:flex-end;gap:2px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--paper);transition:transform 280ms cubic-bezier(.34,1.56,.64,1),opacity 180ms cubic-bezier(.34,1.56,.64,1)}
.d-ts-card:nth-child(1){transform:translateY(16px) translateZ(-28px);opacity:.55}
.d-ts-card:nth-child(2){transform:translateY(8px) translateZ(-14px);opacity:.75}
.d-ts-card:nth-child(3){transform:translateY(0) translateZ(0)}
.d-ts:hover .d-ts-card:nth-child(3),.d-ts:focus-visible .d-ts-card:nth-child(3){transform:translateY(-4px) translateZ(0)}
.d-ts-k{font-family:var(--font-mono);font-size:var(--fs-11);letter-spacing:var(--tracking-mono-label);color:var(--faint)}
.d-ts-n{font-size:var(--fs-15);font-weight:650;line-height:var(--lh-display);letter-spacing:var(--tracking-display);color:var(--ink)}
.d-ts:focus-visible{outline:1px solid var(--ink);outline-offset:6px}

init:
root => {
  const deck = root.querySelector('.d-ts-deck');
  if (!deck || deck.dataset.ts) return;
  deck.dataset.ts = '1';
  const move = e => {
    const r = deck.getBoundingClientRect();
    if (!r.width || !r.height) return;
    const x = (e.clientX - r.left) / r.width - .5;
    const y = (e.clientY - r.top) / r.height - .5;
    deck.style.setProperty('--ry', (x * 8).toFixed(2) + 'deg');
    deck.style.setProperty('--rx', (-y * 6).toFixed(2) + 'deg');
  };
  const rest = () => { deck.style.removeProperty('--rx'); deck.style.removeProperty('--ry'); };
  deck.addEventListener('pointermove', move);
  deck.addEventListener('pointerleave', rest);
  deck.addEventListener('pointercancel', rest);
}
